head.script:
let checkValue = "";

// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > findNodeByIndex]<br/>인덱스값을 사용하여 특정 트리 아이템을 객체로 반환합니다.",
    "validation" : [
        "DateCollection 에서 데이터가 추가/제거 되면 인덱스가 재설정 됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="아이템을 index=2 위치로 추가/삭제 후 checkByIndex 수행하여 확인"', '', 'label1');

    strTarget += '<w2:treeview ' + strNameSpace + ' id="" refreshCheckboxModel="true" showCheckbox="true" dynamicAppend="true" trueValue="t" falseValue="f" style="position: relative;width: 200px;height: 200px;float:left;margin-right:10px;border:1px solid pink;">';
    strTarget += '<w2:itemset nodeset="data:dc_favMenu">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref=""></w2:folder>';
    strTarget += '<w2:checkbox ref="chk"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref=""></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );
}



scwin.btn_addItem_onclick = function (e) {
    dc_favMenu.setRowData(1,["2", "메뉴1-1", "menu1-1", "f"] );    
}



scwin.btn_deleteItem_onclick = function (e) {
	dc_favMenu.removeRow(1);
};



scwin.btn_findNodeByIndex_onclick = function (e) {
    let rtn = null;

    let index = par_index.getText();
    let selected = par_selected.getText();    

    if (selected == "true")
        selected = true;

    if (selected == "false")
        selected = false;

    if (selected == "")
	    rtn = target1.findNodeByIndex(index);
    else
        rtn = target1.findNodeByIndex(index, selected);

    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedLabel : " + target1.getSelectedLabel());
    wf_body_bottom.getObj("scwin").setReturnValue("return object: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("checked : " + rtn.checked);
    wf_body_bottom.getObj("scwin").setReturnValue("checkboxDisabled : " + rtn.checkboxDisabled);
    wf_body_bottom.getObj("scwin").setReturnValue("depth : " + rtn.depth);
    wf_body_bottom.getObj("scwin").setReturnValue("folder : " + rtn.folder);
    wf_body_bottom.getObj("scwin").setReturnValue("index : " + rtn.index);
    wf_body_bottom.getObj("scwin").setReturnValue("label : " + rtn.label);
    wf_body_bottom.getObj("scwin").setReturnValue("value : " + rtn.value);
    wf_body_bottom.getObj("scwin").setReturnValue("parentNode.label : " + rtn.parentNode.label);

    if (rtn.childNodes.length > 0) {
        for (var i=0; i < rtn.childNodes.length; i++)
            wf_body_bottom.getObj("scwin").setReturnValue("childNodes["+i+"].label : " + rtn.childNodes[i].label);
    }
    else {
        wf_body_bottom.getObj("scwin").setReturnValue("childNodes.label : ");
    }
};
